 numbers.add(5);
 numbers.add(1);
 numbers.add(7);
 numbers.add(3);
 numbers.add(9);

 Collections.sort(numbers, Collections.reverseOrder());
 System.out.println(numbers); // [9, 7, 5, 3, 1]
 }
}

